import{_ as e,o as t,c as s,a3 as i}from"./chunks/framework.B9qR_F1m.js";const k=JSON.parse('{"title":"For agents: the skill and llms.txt","description":"","frontmatter":{},"headers":[],"relativePath":"agent-skill.md","filePath":"agent-skill.md"}'),l={name:"agent-skill.md"};function n(o,a,r,h,d,p){return t(),s("div",null,[...a[0]||(a[0]=[i('<h1 id="for-agents-the-skill-and-llms-txt" tabindex="-1">For agents: the skill and <code>llms.txt</code> <a class="header-anchor" href="#for-agents-the-skill-and-llms-txt" aria-label="Permalink to &quot;For agents: the skill and `llms.txt`&quot;">​</a></h1><p>Two files help an AI agent use ripeat safely when it only has a shell, or when it reads the web.</p><h2 id="the-skill" tabindex="-1">The skill <a class="header-anchor" href="#the-skill" aria-label="Permalink to &quot;The skill&quot;">​</a></h2><p>A skill is a short instruction file (<code>SKILL.md</code>) that agent tools such as Claude Code load on demand. ripeat&#39;s skill can guide an agent through installing ripeat and connecting a supported assistant with your agreement. It also teaches the safe flow: write a profile, check it with <code>ripeat validate</code>, preview it with <code>ripeat plan</code> and <code>ripeat assess --json</code>, show the risk in plain words, and <strong>hand the person the <code>ripeat install</code> command to run themselves</strong>. It forbids running the commands that change the machine, adding <code>--yes</code>, <code>--accept-risk</code> or <code>--allow-admin</code>, inventing package names or recipes, and working around a HIGH or BLOCKED rating.</p><p>The <a href="https://github.com/vercel-labs/skills" target="_blank" rel="noreferrer">skills installer</a> can install it from the public documentation site. It requires Node.js and asks which agent and installation scope to use:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ripeat.github.io/skills/ripeat/SKILL.md</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ripeat</span></span></code></pre></div><p>Alternatively, save <a href="https://ripeat.github.io/skills/ripeat/SKILL.md" target="_blank" rel="noreferrer">the file</a> as <code>~/.claude/skills/ripeat/SKILL.md</code> (Claude Code; other agent tools have their own skills folder):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/skills/ripeat</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -fsSL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://ripeat.github.io/skills/ripeat/SKILL.md</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/.claude/skills/ripeat/SKILL.md</span></span></code></pre></div><p>A skill is an instruction, not a lock: an agent with a shell can ignore it. The real protections are ripeat&#39;s own confirmations (<code>--yes</code> does not cover a HIGH-rated plan) and the <a href="./admin-policy">administrator policy</a>. If your assistant supports MCP, <a href="./mcp#connecting"><code>ripeat mcp setup</code></a> is safer, because its tools cannot install at all unless you switch that on.</p><h2 id="llms-txt" tabindex="-1"><code>llms.txt</code> <a class="header-anchor" href="#llms-txt" aria-label="Permalink to &quot;`llms.txt`&quot;">​</a></h2><p><a href="https://ripeat.github.io/llms.txt" target="_blank" rel="noreferrer"><code>https://ripeat.github.io/llms.txt</code></a> is a plain-text index of these docs for agents that read the web: a one-paragraph summary, then each page with its title and a link to its Markdown source (for example <code>https://ripeat.github.io/commands.md</code>). It is built from the same list as the sidebar, so it never lists a page that is not published.</p>',11)])])}const g=e(l,[["render",n]]);export{k as __pageData,g as default};
